"""Explain simple wait structures, initialization, ordering and first-entry wake."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1493': ('대기 줄을 만들려면 줄 전체를 관리하는 표지판과 각 사람의 대기 카드가 필요합니다. 카드에는 누구인지와 옆 카드로 이어지는 연결을 적습니다. 표지판과 카드는 서로 맡은 일이 다릅니다.', 'swait의 줄 전체 자료와 한 작업의 대기 항목을 구별합니다.', '큰 상자 head에는 lock과 task_list를, 작은 상자 entry에는 task와 task_list를 적으세요. task에서 작업으로 화살표를 그리고 task_list끼리 줄을 연결하세요.', ['struct는 관련된 정보를 묶는 C의 자료 형식입니다. swait_queue는 한 작업을 줄에 넣기 위한 자료입니다. 그 안에는 task와 task_list라는 두 멤버, 즉 정보 칸이 있습니다. 이름에 queue가 있어도 이것 하나가 줄 전체인 것은 아닙니다.', 'task의 형식은 struct task_struct *입니다. 별표는 여기서 포인터, 즉 다른 자료의 위치를 담는다는 뜻입니다. task는 기다릴 작업의 정보를 가리킵니다. 작업 본체를 통째로 복사해 담거나 깨우기 함수를 담는 칸이 아닙니다.', 'task_list는 앞뒤 항목을 연결하는 부분입니다. 예를 들어 줄이 A → B → C라면 이 연결을 따라 다음 대기 항목으로 갈 수 있습니다. task가 “누구인가”를 알려 준다면 task_list는 “줄에서 어떻게 이어지는가”를 알려 줍니다.', 'swait_queue_head는 줄 전체를 관리합니다. lock은 여러 실행 흐름이 같은 줄을 동시에 바꾸지 않도록 보호하는 잠금이고, task_list는 줄의 기준점입니다. 기준점은 실제로 기다리는 작업 한 명이 아닙니다. 빈 원형 목록에서는 그 앞뒤 연결이 기준점 자신으로 돌아옵니다.', 'head의 lock 형식은 raw_spinlock_t입니다. mutex처럼 잠들어서 기다리는 잠금이 아니라 낮은 수준의 스핀 잠금입니다. 이 잠금을 잡고 실제 대기 상태로 잠들면 안 됩니다. 줄을 짧게 정리한 뒤 풀고, 실제 기다림은 그 밖에서 해야 합니다.', '일반 wait_queue_entry에 있던 flags, private, func 칸은 이 항목에 없습니다. 따라서 일반 waitqueue 함수에 억지로 형식만 바꾸어 넘길 수 없습니다. 형식 변환은 빠진 칸을 만들어 주지 않습니다. 줄에 연결되어 다른 코드가 접근할 수 있는 동안에는 항목과 관련 자료가 유효하게 남아 있어야 합니다.'], [('swait_queue의 task 칸에는 무엇을 넣나요?', ['사용자가 정한 깨우기 함수의 위치예요', '기다리는 작업의 task_struct 주소예요'], 'task는 struct task_struct *로 선언되어 있습니다. 별표는 주소를 담는 포인터라는 뜻이에요. 사용자 깨우기 함수를 담는 func 칸은 이 구조체에 없습니다.'), ('줄 전체를 보호하는 swait_queue_head의 lock은 어떤 형식인가요?', ['raw_spinlock_t예요', '언제나 mutex예요'], '원문은 raw_spinlock_t lock이라고 선언합니다. 서로 다른 잠금 형식은 사용 규칙도 달라요. 실제로 작업이 잠드는 동안까지 이 raw 잠금을 잡아 두어서는 안 됩니다.')]), 'os1494': ('줄을 세우기 전에 “아직 아무도 없음”이라고 명단을 준비해야 합니다. 이미 사람들이 적힌 명단을 새 빈 종이로 바꾸면 기다리는 사람이 사라진 것처럼 보이겠지요. 초기화는 적절한 때에 해야 합니다.', '대기 줄과 개별 항목의 초기 상태를 구별하고 재초기화의 위험을 이해합니다.', 'head 초기화 옆에는 잠금 준비·이름표 붙이기·빈 줄 만들기를 적으세요. 항목 선언 옆에는 task=current·연결은 자기 자신이라고 적으세요.', ['초기화는 쓰기 전에 시작 상태를 만드는 일입니다. head는 줄 전체를 관리하는 자료이고, 개별 항목은 기다리는 작업 하나를 등록할 자료입니다. 둘 다 연결 칸이 있지만 서로 다른 대상을 준비합니다.', '실행 중 호출하는 __init_swait_queue_head는 먼저 raw_spin_lock_init으로 잠금을 준비합니다. 잠금 자료를 초기화하는 것이지, 호출자가 잠금을 잡고 나오는 동작은 아닙니다. 그다음 lockdep_set_class_and_name을 부릅니다.', 'lockdep는 잠금을 잘못된 순서로 사용하는 문제 등을 찾는 데 도움을 주는 커널 검사 기능입니다. 클래스와 이름은 검사가 잠금을 구분할 때 쓰는 정보입니다. 이름표를 붙였다고 모든 잘못된 사용이 자동으로 고쳐지는 것은 아닙니다.', '마지막 INIT_LIST_HEAD는 head의 task_list 앞뒤가 자기 자신을 가리키게 합니다. 이 원형 목록에서는 그런 연결이 빈 줄을 뜻합니다. 잠금만 만들고 연결 칸을 준비하지 않으면 이후 줄 검사와 등록이 기대하는 상태가 되지 않습니다.', 'DECLARE_SWAITQUEUE(name)는 개별 대기 항목을 선언하면서 task를 current, 즉 지금 실행 중인 작업으로 정합니다. 연결도 자기 자신으로 준비합니다. 반면 DECLARE_SWAIT_QUEUE_HEAD는 줄 전체의 잠금과 빈 목록을 준비합니다. 비슷한 이름에서 HEAD가 있는지 확인하세요.', 'CONFIG_LOCKDEP가 켜진 경우 스택용 head 선언은 실행 중 초기화도 이용해 검사 정보를 준비합니다. 스택은 함수 실행 중 지역 자료를 두는 공간입니다. 그 자료를 더는 쓸 수 없게 되기 전에 대기 등록과 접근을 끝내야 합니다. 이미 사용 중인 줄을 초기화로 비워 버리는 것은 올바른 항목 정리 방법이 아닙니다.'], [('DECLARE_SWAITQUEUE로 내 대기 항목을 만들었어요. task는 처음 무엇을 가리키나요?', ['언제나 대상이 없다는 NULL이에요', 'current, 즉 지금 실행 중인 작업이에요'], '초기화 코드의 .task = current를 보세요. 자기 자신을 가리키는 것은 task가 아니라 task_list의 앞뒤 연결입니다. 작업 주소와 줄 연결을 나누어 읽으면 헷갈리지 않아요.'), ('실행 중 head를 초기화하는 함수는 줄의 앞뒤 연결도 준비하나요?', ['네. INIT_LIST_HEAD로 자신을 가리키는 빈 줄을 만들어요', '아니요. 잠금만 만들고 연결은 그대로 둬요'], '함수는 잠금 준비, 검사 정보 설정, 목록 초기화를 차례로 합니다. 마지막 연결 준비까지 있어야 새 head가 빈 줄이라는 뜻을 갖습니다. 잠금만 준비한다는 답은 마지막 명령을 빠뜨린 것입니다.')]), 'os1495': ('준비물을 가져온 친구는 “기다리는 사람이 없네” 하고 알림을 생략하고, 기다리는 친구는 “아직 준비물이 없네” 하고 잠들면 어떨까요? 서로의 최신 행동을 못 보면 준비물이 있어도 기다림이 끝나지 않을 수 있습니다.', '조건 변경과 대기 등록을 서로 놓치지 않게 하는 순서 규칙을 배웁니다.', '깨우는 쪽에 조건 바꾸기 → 순서 지키기 → 줄 확인을 적으세요. 기다리는 쪽에는 줄 등록·상태 설정 → 조건 다시 확인 → 필요하면 잠들기를 적어 나란히 놓으세요.', ['swait_active는 대기 줄이 비어 있는지 확인합니다. 본문은 !list_empty입니다. 느낌표 !는 결과를 뒤집으므로 줄이 비어 있지 않으면 참입니다. 이 함수 안에는 잠금을 잡거나 푸는 명령이 없습니다.', '잠금 없이 본 값으로 “깨울 필요가 없다”고 결정할 때에는 특별히 조심해야 합니다. 여러 CPU가 자료를 읽고 쓰면 한쪽의 변경과 다른 쪽의 관측 순서가 코드 줄을 읽는 느낌대로 보장되지 않을 수 있기 때문입니다. 단순히 조금 기다리면 해결된다고 볼 문제도 아닙니다.', '예를 들어 깨우는 쪽이 조건을 참으로 바꿨는데도 줄은 비었다고 보고 알림을 생략한다고 해 봅시다. 동시에 기다리는 쪽은 등록한 뒤에도 조건을 거짓으로 보고 잠들 수 있다면 깨움이 빠집니다. 이처럼 필요한 알림을 놓치는 일을 놓친 깨움이라고 합니다.', '원문은 줄의 잠금을 잡고 검사하거나, 잠금 없는 깨움 판단에서는 필요한 smp_mb 규칙을 지키라고 설명합니다. smp_mb는 메모리 배리어, 즉 여러 CPU 사이에서 읽기·쓰기의 순서를 지키도록 하는 명령입니다. 모든 CPU를 같은 시간으로 멈추거나 자료를 잠그는 명령은 아닙니다.', '깨우는 쪽에서는 조건 저장 뒤 배리어를 두고 줄을 봅니다. 기다리는 쪽도 등록과 상태 설정 뒤 조건을 다시 보는 짝이 맞는 순서가 필요합니다. swq_has_sleeper는 smp_mb를 먼저 실행한 뒤 swait_active를 부릅니다. 이 함수 하나만 넣고 반대쪽 규칙을 없애면 안 됩니다.', 'active가 참이라고 그 작업이 바로 지금 잠들어 있다고 단정할 수도 없습니다. 등록한 뒤 아직 잠들기 전일 수 있습니다. 또한 줄을 읽었다고 자료를 계속 사용할 권리를 얻거나 삭제를 막는 것도 아닙니다. 줄의 단순한 모양, 접근 순서, 자료가 유효한 기간은 각각 지켜야 할 문제입니다.'], [('swait_active가 줄을 확인할 때 함수 안에서 raw 잠금을 잡나요?', ['네. 이름이 active인 모든 함수는 잠금을 잡아요', '아니요. 비어 있는지 확인할 뿐이에요'], '본문에는 !list_empty만 있습니다. 함수 이름으로 없는 잠금을 상상하면 안 돼요. 호출하는 쪽에서 필요한 잠금 또는 메모리 순서 규칙을 지켜야 합니다.'), ('swait는 구조가 간단하니 메모리 순서 규칙을 모두 없애도 될까요?', ['아니요. 조건 변경과 대기 등록을 서로 놓치지 않아야 해요', '네. 사용자 콜백이 없으면 여러 CPU의 관측 순서도 자동으로 맞아요'], '콜백 기능을 빼는 일과 여러 CPU가 변경을 관측하는 순서를 지키는 일은 다릅니다. 순서가 맞지 않으면 한쪽은 줄이 비었다고, 다른 쪽은 조건이 거짓이라고 판단해 필요한 깨움을 놓칠 수 있어요.')]), 'os1496': ('줄 맨 앞 친구를 불렀는데 이미 일어나 있었다고 해 봅시다. 이번 규칙은 “방금 새로 일어났는가?”와 별개로 그 친구의 대기 카드를 줄에서 빼는 것입니다. 깨우기 결과와 명단 정리를 따로 보아야 합니다.', '첫 항목의 깨우기 시도와 조건 없는 목록 제거를 구별합니다.', 'A → B → C 줄을 그리고 A 깨우기 결과가 0인 경우와 1인 경우를 나누세요. 두 경우 모두 남은 줄이 B → C인지 확인하세요.', ['swake_up_locked는 호출자가 이미 줄의 raw 잠금을 잡고 있다는 조건에서 사용하는 함수입니다. 이름의 locked는 내부에서 알아서 잠금을 잡는다는 뜻이 아닙니다. 줄을 안전하게 다룰 조건을 호출자가 갖추어야 합니다.', '먼저 list_empty로 줄이 비었는지 봅니다. 비었다면 바로 끝납니다. 사람이 없는 줄에서 첫 항목을 꺼내려 하면 유효한 작업을 얻을 수 없으므로 이 검사가 먼저 필요합니다.', '항목이 있으면 list_first_entry로 맨 앞 하나를 고릅니다. A → B → C라면 A입니다. 뒤까지 돌아다니며 마지막 작업을 찾거나 원하는 상태의 항목을 골라내는 반복문은 이 함수에 없습니다.', '그 항목의 task에 try_to_wake_up을 호출합니다. TASK_NORMAL이라는 대상 상태 묶음과 호출자가 준 wake_flags를 전달합니다. 깨우기 요청은 작업이 실행할 수 있게 하는 과정이지 그 작업이 지금 이 줄에서 즉시 모든 일을 끝냈다는 뜻은 아닙니다.', '그다음 list_del_init으로 항목을 줄에서 빼고 연결을 자기 자신으로 초기화합니다. 깨우기 결과를 담아 if로 검사하지 않으므로 결과가 0이어도 이 정리를 실행합니다. 예를 들어 이미 실행 중이어서 새로 깨울 필요가 없어도 항목은 제거됩니다. 항목의 메모리까지 해제하는 동작은 아닙니다.', '일반 대기 줄의 autoremove_wake_function은 깨우기 결과가 0이 아닐 때만 제거하지만 이 함수는 다릅니다. 다시 기다려야 할 경우에는 대기 반복문이 조건을 확인하고 필요한 등록을 다시 합니다. 그래서 “깨움 시도”, “줄에서 제거”, “조건 충족”을 같은 사건으로 합쳐 생각하지 마세요.'], [('첫 작업의 try_to_wake_up 결과가 0이었어요. swake_up_locked는 그 항목을 줄에서 빼나요?', ['아니요. 결과가 성공일 때만 빼요', '네. 결과를 조건으로 검사하지 않고 빼요'], '호출 바로 다음 명령이 list_del_init이고 그 앞에 결과를 검사하는 if가 없습니다. 이미 실행 중이라 결과가 0이어도 정리를 진행해요. 일반 autoremove 콜백의 조건부 삭제와 구별하세요.'), ('A → B → C 순서의 줄에서 swake_up_locked가 다루는 항목은?', ['맨 앞 A 하나예요', '모든 항목의 상태를 살펴 마지막 C를 골라요'], 'list_first_entry가 첫 항목 A를 고릅니다. 이 함수에는 끝까지 훑는 반복문이 없어요. A에 깨우기를 시도하고 A의 연결을 정리한 뒤 끝납니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_369.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
